import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"1980年 · 留存收益的隐藏价值","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1980年.md","filePath":"05_quotes/by-year/1980年.md"}'),r={name:"05_quotes/by-year/1980年.md"};function s(c,e,h,u,_,i){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_1980年-·-留存收益的隐藏价值" tabindex="-1">1980年 · 留存收益的隐藏价值 <a class="header-anchor" href="#_1980年-·-留存收益的隐藏价值" aria-label="Permalink to &quot;1980年 · 留存收益的隐藏价值&quot;">​</a></h1><blockquote><p>传统会计只让我们收益冰山不到一半露出水面，摆在明面上。在企业界这种情况相当罕见；在我们这里，它可能会反复出现。——巴菲特（50岁）</p></blockquote><p>本页收录1980年致股东信中的经典语录。这一年巴菲特讲透了非控股股权收益的真实价值：会计准则只算你拿到的股息，不算你应得的留存收益，但真正的价值来自企业盈利。同时对保险行业长期债券大雷做出精准预言。ROE为17.8%。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>传统会计只让我们收益冰山不到一半露出水面，摆在明面上。在企业界这种情况相当罕见；在我们这里，它可能会反复出现。</p></blockquote><blockquote><p>留存收益对伯克希尔的价值，不取决于我们拥有企业100%、50%、20%还是1%，而是取决于留存收益怎么用，以及使用之后产生的盈利水平。</p></blockquote><blockquote><p>如果一片森林长在我们部分拥有的树林里，哪怕我们财务报表没记录生长，我们依然拥有一部分树。</p></blockquote><blockquote><p>我们投资的公司，如果它们留存收益用来回购自家股票，我们通常会特别热情。道理很简单：如果一家好企业市场售价远低于内在价值，还有什么比用这个便宜价格显著扩大所有股东权益更确定、更赚钱的资本用途呢？</p></blockquote><blockquote><p>我们这个观点是非传统的。但我们宁愿，我们没拿到会计credit的盈利，被我们没亲自雇的管理层用好，投在10%持股的公司里，也不愿意credit拿到了，却被另一个管理层投到潜力更不确定的项目里——哪怕那个管理层就是我们自己。</p></blockquote><blockquote><p>GEICO就是设计成为汽车保险这个巨大市场的低成本运营商，这个市场里大多数公司营销结构限制了适应能力。按设计运营，它就能给客户提供不同寻常的价值，同时自己赚不同寻常的回报。</p></blockquote><blockquote><p>GEICO过去的问题，就像1964年色拉油丑闻后的美国运通。都是独一无二的公司，暂时被财政打击晃了一下，但根本没有摧毁它们底层经济。</p></blockquote><blockquote><p>很多保险公司被债券套牢了：过去买了很多长期债券，现在利率上涨，债券价格大跌，但会计允许按摊余成本持有，不用认跌价。</p></blockquote><blockquote><p>我们偏好能产生现金的企业，不喜欢消耗现金的，保持流动性和充足资本，睡得香。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1980年巴菲特详细解释了会计准则对不同持股比例的会计处理不同，揭示了留存收益的真实价值。伊利诺伊国民银行完成分拆，创始人吉恩·阿贝格去世，巴菲特给予极高评价。GEICO成为最大重仓股，持有720万股、33%股权。巴菲特对保险行业长期债券问题提出警示，预言很多保险公司会被债券套牢，只能低价抢业务维持现金流。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1980年-翻译-·-01-letters-1980年-核心总结-·-01-letters-1980年-思维导图" tabindex="-1"><a href="/01_letters/1980年/翻译.html">01_letters/1980年/翻译</a> · <a href="/01_letters/1980年/核心总结.html">01_letters/1980年/核心总结</a> · <a href="/01_letters/1980年/思维导图.html">01_letters/1980年/思维导图</a> <a class="header-anchor" href="#_01-letters-1980年-翻译-·-01-letters-1980年-核心总结-·-01-letters-1980年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1980年/翻译]] · [[→ 核心总结|01_letters/1980年/核心总结]] · [[→ 思维导图|01_letters/1980年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1980年/翻译.html">/01_letters/1980年/翻译</a></li></ul>',22)])])}const q=t(r,[["render",s]]);export{p as __pageData,q as default};
